def find_zero(xs: list):
    """
    Finds a zero point of the polynomial with coefficients xs.
    Returns one real root, prioritizing roots closer to zero.
    """
    if not xs:
        return 0.0

    # Remove trailing zero coefficients to get the true degree
    i = len(xs) - 1
    while i >= 0 and xs[i] == 0:
        i -= 1
    if i < 0:
        return 0.0
    xs = xs[:i + 1]

    def f(x):
        y = xs[-1]
        for c in reversed(xs[:-1]):
            y = y * x + c
        return y

    def sign(x):
        if x > 0:
            return 1
        elif x < 0:
            return -1
        else:
            return 0

    def bisection(low, high):
        fl = f(low)
        if abs(fl) < 1e-12:
            return low
        fh = f(high)
        if abs(fh) < 1e-12:
            return high
        for _ in range(100):
            mid = (low + high) / 2
            fm = f(mid)
            if abs(fm) < 1e-12:
                return mid
            if sign(fl) != sign(fm):
                high = mid
            else:
                low = mid
                fl = fm
        return (low + high) / 2

    # Check if zero is a root
    if abs(f(0)) < 1e-12:
        return 0.0

    # Compute a bound for all real roots
    lead = xs[-1]
    if lead == 0:
        return 0.0
    M = 1.0
    for c in xs[:-1]:
        if c != 0:
            M = max(M, abs(c) / abs(lead))
    M = 1 + M

    # Search symmetric intervals expanding from zero
    scale = 1.0
    while scale <= M and math.isfinite(scale):
        low, high = -scale, scale
        if abs(f(low)) < 1e-12:
            return low
        if abs(f(high)) < 1e-12:
            return high
        if sign(f(low)) != sign(f(high)):
            return bisection(low, high)
        scale *= 2

    # Fallback: bisection over the full root bound
    if abs(f(-M)) < 1e-12:
        return -M
    if abs(f(M)) < 1e-12:
        return M
    if sign(f(-M)) != sign(f(M)):
        return bisection(-M, M)

    # Newton's method fallback
    def df(x):
        y = len(xs) * xs[-1]
        for i in range(len(xs) - 2, 0, -1):
            y = y * x + i * xs[i]
        return y

