def max_product(arr, n):
    if n <= 0:
        return 0

    max_prod = [0] * n
    min_prod = [0] * n

    for i in range(n):
        max_prod[i] = arr[i]
        min_prod[i] = arr[i]

        for j in range(i):
            if arr[j] < arr[i]:
                p1 = max_prod[j] * arr[i]
                p2 = min_prod[j] * arr[i]

                max_prod[i] = max(max_prod[i], p1, p2)
                min_prod[i] = min(min_prod[i], p1, p2)

    return max(max_prod)
