def removals(arr, k):
    if not arr:
        return 0
    n = len(arr)
    if k < 0:
        return max(0, n - 1)
    arr.sort()
    left = 0
    max_size = 0
    for right in range(n):
        while arr[right] - arr[left] > k:
            left += 1
        max_size = max(max_size, right - left + 1)
    return n - max_size
